func TestValidateImageDimensionsAcceptsRegularImage(t *testing.T) {
	t.Parallel()

	if err := ValidateImageDimensions(encodePNG(t, 40, 30)); err != nil {
		t.Fatalf("expected regular image to pass, got %v", err)
